/** Supplied-store acceptance only: it never generates or imports a dataset. */
@EnabledIfSystemProperty(named = "rdf4j.lmdb.startup.acceptance.store", matches = ".+")
class LmdbStartupAcceptanceTest {

	@Test
	void suppliedRepositoryIsReadyWithinItsForegroundReadBudget() throws Exception {
		Path directory = Path.of(System.getProperty("rdf4j.lmdb.startup.acceptance.store")).toAbsolutePath();
		LmdbStoreConfig config = configuration(directory);
		SailRepository repository = null;
		try {
			long readyNanos;
			long reads;
			long drops;
			TreeMap<String, Long> categories;
			LmdbStore store;
			try (var counter = new LmdbStartupReadCounter()) {
				long started = System.nanoTime();
				store = new LmdbStore(directory.toFile(), config);
				repository = new SailRepository(store);
				repository.init();
				readyNanos = System.nanoTime() - started;
				reads = counter.total();
				drops = counter.treeDrops();
				categories = new TreeMap<>(counter.operations());
			}
			LmdbStore.StartupStatus status = store.getStartupStatus();
			long firstQueryStarted = System.nanoTime();
			try (var connection = repository.getConnection();
					var result = connection.prepareTupleQuery("SELECT ?s WHERE { ?s ?p ?o } LIMIT 1").evaluate()) {
				if (result.hasNext()) {
					result.next();
				}
			}
			long firstQueryNanos = System.nanoTime() - firstQueryStarted;
			long explicitStatements;
			long inferredStatements;
			// Unbound native count uses B-tree entry statistics, not a record cursor. It is outside both timings.
			try (var explicit = store.getBackingStore().getExplicitSailSource().dataset(IsolationLevels.SNAPSHOT);
					var inferred = store.getBackingStore().getInferredSailSource().dataset(IsolationLevels.SNAPSHOT)) {
				explicitStatements = ((NativeLmdbQuerySource) explicit).count(-1, -1, -1, -1);
				inferredStatements = ((NativeLmdbQuerySource) inferred).count(-1, -1, -1, -1);
			}
			String nativeCategories = categories.entrySet()
					.stream()
					.map(entry -> quote(entry.getKey()) + ": " + entry.getValue())
					.collect(Collectors.joining(", "));
			String report = "{\n"
					+ "  \"explicitStatements\": " + explicitStatements + ",\n"
					+ "  \"inferredStatements\": " + inferredStatements + ",\n"
					+ "  \"statementCount\": " + (explicitStatements + inferredStatements) + ",\n"
					+ "  \"readyMillis\": " + readyNanos / 1_000_000.0 + ",\n"
					+ "  \"foregroundLogicalReads\": " + reads + ",\n"
					+ "  \"readCategories\": {" + nativeCategories + "},\n"
					+ "  \"foregroundTreeDrops\": " + drops + ",\n"
					+ "  \"exactReferenceCounts\": " + status.exactReferenceCounts() + ",\n"
					+ "  \"referenceCountVerificationPending\": " + status.referenceCountVerificationPending() + ",\n"
					+ "  \"retainedValueMaintenance\": " + status.retainedValueMaintenance() + ",\n"
					+ "  \"optionalMaintenancePending\": " + status.optionalMaintenancePending() + ",\n"
					+ "  \"backgroundWorkPending\": " + status.backgroundWorkPending() + ",\n"
					+ "  \"statementIndexBuild\": " + quote(status.statementIndexBuild()) + ",\n"
					+ "  \"tripleTermIndexBuild\": " + quote(status.tripleTermIndexBuild()) + ",\n"
					+ "  \"auxiliaryMaintenance\": " + quote(status.auxiliaryMaintenance()) + ",\n"
					+ "  \"firstQueryMillis\": " + firstQueryNanos / 1_000_000.0 + "\n}\n";
			System.out.println(report);
			String output = System.getProperty("rdf4j.lmdb.startup.acceptance.output");
			if (output != null) {
				Files.writeString(Path.of(output), report, StandardOpenOption.CREATE_NEW);
			}
			assertTrue(reads <= 1_000, () -> "Foreground read budget exceeded: " + categories);
			assertEquals(0L, drops, "readiness must not delete whole native trees");
			String maximum = System.getProperty("rdf4j.lmdb.startup.acceptance.maxReadyMillis");
			if (maximum != null) {
				assertTrue(readyNanos / 1_000_000.0 < Double.parseDouble(maximum), "readiness exceeded timing target");
			}
		} finally {
			if (repository != null) {
				repository.shutDown();
			}
		}
	}

	private static LmdbStoreConfig configuration(Path directory) throws IOException {
		StoreProperties properties = new StoreProperties(directory.toFile());
		properties.load();
		LmdbStoreConfig config = new LmdbStoreConfig()
				.setInlineLiterals(!"false".equals(properties.inlineLiterals));
		config.setTripleIndexes(properties.getTripleIndexes());
		config.setTripleTermIndexes(properties.getTripleTermIndexes());
		String configuration = System.getProperty("rdf4j.lmdb.startup.acceptance.config");
		if (configuration != null) {
			Path file = Path.of(configuration);
			try (var input = Files.newInputStream(file)) {
				var model = Rio.parse(input, file.toUri().toString(), RDFFormat.TURTLE);
				Set<Resource> nodes = model.stream()
						.filter(statement -> statement.getPredicate().equals(CONFIG.Sail.type)
								|| statement.getPredicate().equals(SailConfigSchema.SAILTYPE))
						.filter(statement -> statement.getObject().stringValue().equals(LmdbStoreFactory.SAIL_TYPE))
						.map(Statement::getSubject)
						.collect(Collectors.toSet());
				if (nodes.size() != 1) {
					throw new IOException("Configuration must contain exactly one RDF4J LMDB Sail node");
				}
				config.parse(model, nodes.iterator().next());
			}
		}
		String statements = System.getProperty("rdf4j.lmdb.startup.acceptance.tripleIndexes");
		String terms = System.getProperty("rdf4j.lmdb.startup.acceptance.termIndexes");
		if (statements != null) {
			config.setTripleIndexes(statements);
		}
		if (terms != null) {
			config.setTripleTermIndexes(terms);
		}
		return config;
	}

	private static String quote(String text) {
		return '"' + text.replace("\\", "\\\\")
				.replace("\"", "\\\"")
				.replace("\n", "\\n")
				.replace("\r", "\\r")
				.replace("\t", "\\t") + '"';
	}
}
